#include <iostream>
#include "loose_collision_scene_test_fixture.h"
#include "physics_search_test_fixture.h"
int main(int argc,char**argv){try{
    static_assert(sizeof(void*)==8,"owned x64");if(argc!=5)throw std::runtime_error("BSP mounts queries output required");LooseCollisionSceneTestFixture f(argv[1],argv[2]);std::ifstream in(argv[3],std::ios::binary);std::ofstream out(argv[4],std::ios::binary),events(std::string(argv[4])+".events",std::ios::binary),models(std::string(argv[4])+".models",std::ios::binary),states(std::string(argv[4])+".registrations",std::ios::binary),sources(std::string(argv[4])+".sources");if(!in||!out||!events||!models||!states||!sources)throw std::runtime_error("loose scene fixture streams");
    sources<<f.assets.manifestSource().string()<<'\n';for(const auto&p:f.assets.scriptSources())sources<<p.string()<<'\n';for(const auto&p:f.assets.modelSources())sources<<p.string()<<'\n';
    for(size_t i=0;i<f.modelIds.size();++i){const auto&s=f.assets.modelSurfaces()[i];supportPut(models,f.modelIds[i]);supportPut(models,s.model);supportPut(models,uint32_t(s.bones.size()));for(auto x:s.bones)supportPut(models,x);}
    for(size_t i=0;i<f.entityIds.size();++i){const auto&r=f.scene.registrationAt(i);supportPut(states,r.entityId);supportPut(states,r.diskSolidType);supportPut(states,r.effectiveSolidType);supportPut(states,uint32_t(r.partitionHandle));supportPut(states,uint32_t(bool(r.physicalBounds)));supportPut(states,r.physicalBounds.value_or(std::array<float,6>{}));}
    size_t count=0;while(in.peek()!=std::char_traits<char>::eof()){uint64_t id=0,world=0;uint32_t mask=0;SourceWorldLightRayCandidate ray;supportGet(in,id);supportGet(in,ray.start);supportGet(in,ray.delta);supportGet(in,mask);supportGet(in,world);ray.swept=((ray.delta[0]*ray.delta[0]+ray.delta[1]*ray.delta[1])+ray.delta[2]*ray.delta[2])!=0;const auto result=f.scene.runtimeLease(id).clip(ray,mask,world);searchWriteTrace(out,result.trace);supportPut(events,uint32_t(result.physicsDispatched));supportPut(events,uint32_t(result.trace.fraction<1||result.trace.startSolid||result.trace.allSolid));++count;}
    if(!count)throw std::runtime_error("loose scene query corpus empty");out.flush();events.flush();models.flush();states.flush();sources.flush();if(!out||!events||!models||!states||!sources)throw std::runtime_error("loose scene output failure");std::cout<<"PASS configured loose collision scene models="<<f.modelIds.size()<<" props="<<f.entityIds.size()<<" queries="<<count<<" real resolved surfaces/runtime solid state\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
